-- Prepared only. No activation or modification of existing balances, XP or progress.
create table versus_private.tower_rollout(singleton boolean primary key default true check(singleton),enabled boolean not null default false,payments_enabled boolean not null default false,global_enabled boolean not null default false,pilot_users uuid[] not null default '{}' check(array_position(pilot_users,null) is null));
create table versus_private.tower_definitions(key text primary key,character_key text not null,floor integer not null check(floor between 1 and 10),rival text not null,config jsonb not null,unique(character_key,floor));
create table versus_private.tower_words(word_id integer primary key,language text not null check(language in ('es','en','pt-BR')),theme text not null,word text not null,word_key text not null);
create table versus_private.tower_pools(definition text references versus_private.tower_definitions,language text not null,theme text not null,word_ids integer[] not null check(cardinality(word_ids)>=9),primary key(definition,language,theme));
create table versus_private.tower_category_rotation(user_id uuid references auth.users(id) on delete cascade,character_key text not null,remaining text[] not null default '{}',primary key(user_id,character_key));
create table versus_private.tower_attempts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,request_id uuid not null,definition text not null references versus_private.tower_definitions,language text not null check(language in ('es','en','pt-BR')),state jsonb not null,sequence bigint not null default 0 check(sequence between 0 and 4096),status text not null default 'prepared' check(status in ('prepared','playing','won','lost','draw','abandoned','expired')),created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),unique(user_id,request_id));
create unique index tower_one_active_attempt on versus_private.tower_attempts(user_id) where status in ('prepared','playing');
create index tower_attempts_owner_status on versus_private.tower_attempts(user_id,status,created_at);
create table versus_private.tower_action_receipts(attempt_id uuid references versus_private.tower_attempts(id) on delete cascade,request_id uuid not null,action text not null,expected_sequence bigint,payload jsonb not null,response jsonb not null,created_at timestamptz not null default clock_timestamp(),primary key(attempt_id,request_id));
create table versus_private.tower_verified_floors(user_id uuid references auth.users(id) on delete cascade,character_key text not null,floor integer not null check(floor between 1 and 10),attempt_id uuid not null references versus_private.tower_attempts(id),verified_at timestamptz not null default clock_timestamp(),primary key(user_id,character_key,floor),foreign key(character_key,floor) references versus_private.tower_definitions(character_key,floor));
create table versus_private.tower_progress(user_id uuid references auth.users(id) on delete cascade,character_key text not null,completed integer not null default 0 check(completed between 0 and 10),updated_at timestamptz not null default clock_timestamp(),primary key(user_id,character_key),check(character_key=any(array['explorador','mago','guardiana','dragon','hombre_lobo','guardian_alba','dragon_hielo','kalamo','kairos','t_shadow','azrak'])));
create table versus_private.tower_coin_receipts(id uuid not null unique default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,character_key text not null,floor integer not null check(floor between 1 and 10),attempt_id uuid not null references versus_private.tower_attempts(id),amount integer not null,awarded_at timestamptz not null default clock_timestamp(),primary key(user_id,character_key,floor),foreign key(user_id,character_key,floor) references versus_private.tower_verified_floors(user_id,character_key,floor),check(amount=case when floor<=4 then 30 when floor<=9 then 50 else 150 end));
do $tables$ declare t text;begin foreach t in array array['tower_rollout','tower_definitions','tower_words','tower_pools','tower_category_rotation','tower_attempts','tower_action_receipts','tower_verified_floors','tower_progress','tower_coin_receipts'] loop execute format('alter table versus_private.%I enable row level security',t);execute format('revoke all on versus_private.%I from public,anon,authenticated,service_role',t);end loop;end $tables$;
create function versus_private.tower_server_now() returns timestamptz language sql volatile set search_path='' as $$select clock_timestamp()$$;


-- Dedicated Tower engine. Existing Adventure and multiplayer functions stay untouched.
create function versus_private.tower_duel_bank(p_language text,p_version text)
returns table(language text,theme text,word_id integer,word text,word_key text)
language sql stable security definer set search_path='' as $$
 select w.language,w.theme,w.word_id,w.word,w.word_key from versus_private.tower_words w
 join versus_private.tower_pools p on p.language=w.language and p.theme=w.theme and w.word_id=any(p.word_ids)
 where p.definition=p_version and p.language=p_language
$$;
create function versus_private.tower_duel_actor(p_definition text,p_language text,p_theme text default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare theme_ text:=p_theme;words_ jsonb;
begin
 if theme_ is null then select theme into strict theme_ from versus_private.tower_pools where definition=p_definition and language=p_language order by random() limit 1;end if;
 select jsonb_agg(word_id) into words_ from (select word_id from versus_private.tower_duel_bank(p_language,p_definition) where theme=theme_ order by random() limit 5) q;
 if jsonb_array_length(words_) is distinct from 5 then raise exception 'Tower word bank unavailable';end if;
 return jsonb_build_object('theme',theme_,'bankVersion',p_definition,'words',words_,'index',0,'letters','[]'::jsonb,'errors',0,'lives',5,'completed',0,'charge',0,'hint','','finished',false,'effect','','effect_until',null,'deadline',null);
end $$;

CREATE OR REPLACE FUNCTION versus_private.tower_duel_event(s jsonb, e jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
 select s||jsonb_build_object('event_seq',(s->>'event_seq')::integer+1,'events',
  (select jsonb_agg(value order by ordinality) from jsonb_array_elements(coalesce(s->'events','[]'::jsonb)||jsonb_build_array(e||jsonb_build_object('seq',(s->>'event_seq')::integer+1))) with ordinality where ordinality>greatest(0,jsonb_array_length(coalesce(s->'events','[]'::jsonb))+1-24)))
$function$
;

CREATE OR REPLACE FUNCTION versus_private.tower_duel_resolve(p_state jsonb, p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
 declare s jsonb:=p_state;p jsonb:=s->'player';n jsonb:=s->'npc';winner_ text:='';pt timestamptz;nt timestamptz;
begin
 if (s->>'finished')::boolean or not (s->>'started')::boolean then return s;end if;
 pt:=case when not (p->>'finished')::boolean then (p->>'deadline')::timestamptz end;
 nt:=case when not (n->>'finished')::boolean then (n->>'deadline')::timestamptz end;
 if (p->>'lives')::integer<=0 then winner_:='npc';elsif (n->>'lives')::integer<=0 then winner_:='player';
 elsif pt<=p_now and nt<=p_now and pt=nt then winner_:=case when (p->>'lives')::integer>(n->>'lives')::integer then 'player' when (p->>'lives')::integer<(n->>'lives')::integer then 'npc' else 'draw' end;
 elsif pt<=p_now and (nt>p_now or pt<nt) then winner_:='npc';elsif nt<=p_now then winner_:='player';
 elsif (p->>'finished')::boolean and (n->>'finished')::boolean then winner_:=case when (p->>'lives')::integer>(n->>'lives')::integer then 'player' when (p->>'lives')::integer<(n->>'lives')::integer then 'npc' else 'draw' end;
 end if;
 if winner_<>'' then
  s:=s||jsonb_build_object('finished',true,'winner',winner_,'done',winner_='player','finished_at',p_now);
  s:=versus_private.tower_duel_event(s,jsonb_build_object('type','result','winner',winner_));
 end if;
 return s;
end $function$
;

CREATE OR REPLACE FUNCTION versus_private.tower_duel_word(p_state jsonb, p_actor text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select w.word_key from versus_private.tower_duel_bank(p_state->>'language',coalesce(p_state->p_actor->>'bankVersion','legacy-v1')) w where w.language=p_state->>'language' and w.theme=p_state->p_actor->>'theme' and w.word_id=(p_state->p_actor->'words'->>((p_state->p_actor->>'index')::integer))::integer
$function$
;

CREATE OR REPLACE FUNCTION versus_private.tower_duel_letter(p_state jsonb, p_actor text, p_letter text, p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s jsonb:=p_state;a jsonb:=s->p_actor;other_ text:=case when p_actor='player' then 'npc' else 'player' end;b jsonb:=s->other_;word_ text;letters_ text[];won boolean;failed boolean;extra_ integer;amount_ integer;idx integer;
begin
 if (s->>'finished')::boolean or (a->>'finished')::boolean then return s;end if;
 word_:=versus_private.tower_duel_word(s,p_actor);if word_ is null then raise exception 'No hay palabra activa.';end if;
 if p_letter is null or length(p_letter)<>1 or position(p_letter in case when s->>'language'='es' then 'QWERTYUIOPASDFGHJKLÑZXCVBNM' else 'QWERTYUIOPASDFGHJKLZXCVBNM' end)=0 then raise exception 'Letra inválida.' using errcode='22023';end if;
 if a->'letters' @> jsonb_build_array(p_letter) then return s;end if;
 a:=jsonb_set(a,'{letters}',a->'letters'||to_jsonb(p_letter));
 amount_:=length(word_)-length(replace(word_,p_letter,''));
 if amount_>0 then a:=jsonb_set(a,'{charge}',to_jsonb(least(8,(a->>'charge')::integer+amount_)));else a:=jsonb_set(a,'{errors}',to_jsonb((a->>'errors')::integer+1));end if;
 if a->>'hint'=p_letter then a:=jsonb_set(a,'{hint}','""');end if;
 select coalesce(array_agg(value),'{}') into letters_ from jsonb_array_elements_text(a->'letters');
 won:=not exists(select 1 from generate_series(1,length(word_)) i where not substr(word_,i,1)=any(letters_));failed:=(a->>'errors')::integer>=6;
 s:=versus_private.tower_duel_event(s,jsonb_build_object('type','letter','actor',p_actor,'letter',p_letter,'correct',amount_>0));
 if won or failed then
  idx:=(a->>'index')::integer+1;a:=a||jsonb_build_object('index',idx,'letters','[]'::jsonb,'errors',0,'hint','');
  if won then a:=jsonb_set(a,'{completed}',to_jsonb((a->>'completed')::integer+1));b:=jsonb_set(b,'{lives}',to_jsonb((b->>'lives')::integer-1));
  else
   a:=jsonb_set(a,'{lives}',to_jsonb((a->>'lives')::integer-1));
   if (a->>'lives')::integer>0 then
    select w.word_id into extra_ from versus_private.tower_duel_bank(s->>'language',coalesce(a->>'bankVersion','legacy-v1')) w where w.language=s->>'language' and w.theme=a->>'theme' and not (a->'words' @> to_jsonb(array[w.word_id])) order by gen_random_uuid() limit 1;
    if extra_ is not null then a:=jsonb_set(a,'{words}',a->'words'||to_jsonb(extra_));end if;
   end if;
  end if;
  if (a->>'completed')::integer>=5 then a:=jsonb_set(a,'{finished}','true');end if;
  if a->>'effect'='forced_miss' then a:=a||jsonb_build_object('effect','','effect_until',null);end if;
  s:=versus_private.tower_duel_event(s,jsonb_build_object('type','word','actor',p_actor,'correct',won,'reveal',case when failed then word_ else null end));
 end if;
 s:=jsonb_set(jsonb_set(s,array[p_actor],a),array[other_],b);
 return versus_private.tower_duel_resolve(s,p_now);
end $function$
;

CREATE OR REPLACE FUNCTION versus_private.tower_duel_advance(p_state jsonb, p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s jsonb:=p_state;next_ timestamptz;impact_ timestamptz;tick_ timestamptz;deadline_ timestamptz;e jsonb;
 a jsonb;effect_ text;word_ text;alphabet_ text;correct_ text[];wrong_ text[];options_ text[];letter_ text;prob_ double precision;old_index integer;iterations integer:=0;
begin
 if not (s->>'started')::boolean or (s->>'finished')::boolean then return s;end if;
 loop
  exit when (s->>'finished')::boolean;
  iterations:=iterations+1;if iterations>1024 then raise exception 'Demasiados eventos de duelo.' using errcode='54000';end if;
  select min((value->>'impact_at')::timestamptz) into impact_ from jsonb_array_elements(s->'pending');
  tick_:=case when (s->'npc'->>'finished')::boolean then null else (s->>'next_tick')::timestamptz end;
  deadline_:=least(case when not(s->'player'->>'finished')::boolean then (s->'player'->>'deadline')::timestamptz end,case when not(s->'npc'->>'finished')::boolean then (s->'npc'->>'deadline')::timestamptz end);
  next_:=least(impact_,tick_,deadline_);exit when next_ is null or next_>p_now;
  if deadline_=next_ then s:=versus_private.tower_duel_resolve(s,next_);exit when (s->>'finished')::boolean;
  elsif impact_=next_ then
   select value into e from jsonb_array_elements(s->'pending') where (value->>'impact_at')::timestamptz=impact_ limit 1;
   s:=jsonb_set(s,'{pending}',coalesce((select jsonb_agg(value) from jsonb_array_elements(s->'pending') where value<>e),'[]'::jsonb));
   s:=versus_private.tower_duel_impact(s,e,next_);
  else
   s:=jsonb_set(s,'{next_tick}',to_jsonb(tick_+make_interval(secs=>(s->'config'->>'interval')::numeric/1000)));
   a:=s->'npc';effect_:=case when (a->>'effect_until')::timestamptz>tick_ then a->>'effect' else '' end;
   if effect_ in ('roots','black_hole','key_bounce','ice_screen','key_theft','time_steal','forced_miss') then continue;end if;
   s:=versus_private.tower_duel_ability(s,'npc',tick_);a:=s->'npc';old_index:=(a->>'index')::integer;
   word_:=versus_private.tower_duel_word(s,'npc');alphabet_:=case when s->>'language'='es' then 'QWERTYUIOPASDFGHJKLÑZXCVBNM' else 'QWERTYUIOPASDFGHJKLZXCVBNM' end;
   select array_agg(letter order by first_) into correct_ from (select substr(word_,i,1) letter,min(i) first_ from generate_series(1,length(word_)) i group by substr(word_,i,1)) q where not(a->'letters' @> jsonb_build_array(letter));
   select array_agg(substr(alphabet_,i,1) order by i) into wrong_ from generate_series(1,length(alphabet_)) i where position(substr(alphabet_,i,1) in word_)=0 and not(a->'letters' @> jsonb_build_array(substr(alphabet_,i,1)));
   prob_:=case when effect_ in ('roar','shuffle') then 0.25 else (s->'config'->>'probability')::double precision end;
   if coalesce(a->>'hint','')<>'' then letter_:=a->>'hint';
   else
    options_:=case when random()<prob_ or cardinality(wrong_) is null then correct_ else wrong_ end;
    letter_:=options_[1+floor(random()*cardinality(options_))::integer];
   end if;
   if letter_ is null then continue;end if;
   s:=versus_private.tower_duel_letter(s,'npc',letter_,tick_);
   if not (s->>'finished')::boolean and (s->'npc'->>'index')::integer=old_index then s:=versus_private.tower_duel_ability(s,'npc',tick_);end if;
  end if;
 end loop;
 return versus_private.tower_duel_resolve(s,p_now);
end $function$
;

create function versus_private.tower_duel_ability(p_state jsonb,p_actor text,p_now timestamptz)
returns jsonb language plpgsql security definer set search_path='' as $$
declare s jsonb:=p_state;a jsonb:=s->p_actor;effect_ text;delay_ integer;hint_ text;word_ text;e jsonb;
begin
 if (s->>'finished')::boolean or (a->>'finished')::boolean or (a->>'charge')::integer<8 then return s;end if;
 if p_actor='npc' and s->'config'->>'rival'='dragon_hielo' and coalesce((s->>'nybor_ready_at')::timestamptz,p_now)>p_now then return s;end if;
 effect_:=s->'config'->>case when p_actor='player' then 'playerEffect' else 'npcEffect' end;
 delay_:=(s->'config'->>case when p_actor='player' then 'playerWindup' else 'windup' end)::integer;
 if (s->>'reduced')::boolean then delay_:=80;end if;
 if effect_='hint' then
  word_:=versus_private.tower_duel_word(s,p_actor);
  select letter into hint_ from (select substr(word_,i,1) letter from generate_series(1,length(word_)) i group by substr(word_,i,1)) q where not(a->'letters' @> jsonb_build_array(letter)) order by random() limit 1;
  if hint_ is null then return s;end if;
 end if;
 if p_actor='npc' and s->'config'->>'rival'='dragon_hielo' then s:=s||jsonb_build_object('nybor_ready_at',p_now+make_interval(secs=>delay_::numeric/1000+17));end if;
 e:=jsonb_build_object('actor',p_actor,'kind',effect_,'impact_at',p_now+make_interval(secs=>delay_::numeric/1000),'hint',coalesce(hint_,''),'union',p_actor='player' and coalesce((s->'config'->>'playerUnion')::boolean,false));
 a:=jsonb_set(a,'{charge}','0');s:=jsonb_set(s,array[p_actor],a);s:=jsonb_set(s,'{pending}',s->'pending'||jsonb_build_array(e));
 return versus_private.tower_duel_event(s,jsonb_build_object('type','ability','actor',p_actor,'effect',effect_,'windup',delay_));
end $$;
create function versus_private.tower_duel_impact(p_state jsonb,p_event jsonb,p_now timestamptz)
returns jsonb language plpgsql security definer set search_path='' as $$
declare s jsonb:=p_state;actor_ text:=p_event->>'actor';target_ text:=case when actor_='player' then 'npc' else 'player' end;
 effect_ text:=p_event->>'kind';a jsonb;word_ text;alphabet_ text;letter_ text;e jsonb;
begin
 if (s->>'finished')::boolean then return s;end if;
 if effect_='hint' then
  s:=jsonb_set(s,array[actor_,'hint'],to_jsonb(p_event->>'hint'));
  if coalesce((p_event->>'union')::boolean,false) then s:=jsonb_set(s,array[target_],(s->target_)||jsonb_build_object('effect','roots','effect_until',greatest(coalesce((s->target_->>'effect_until')::timestamptz,p_now),p_now+interval '2 seconds')));end if;
 elsif effect_='time_steal' then
  a:=s->target_;a:=a||jsonb_build_object('deadline',(a->>'deadline')::timestamptz-interval '20 seconds','effect','time_steal','effect_until',p_now+interval '2 seconds');s:=jsonb_set(s,array[target_],a);
 elsif effect_='forced_miss' and target_='player' then
  a:=s->target_;s:=jsonb_set(s,array[target_],a||jsonb_build_object('effect','forced_miss','effect_until',p_now+interval '2 seconds'));
  e:=jsonb_build_object('actor',actor_,'kind','forced_letter','impact_at',p_now+interval '2 seconds','word_index',(a->>'index')::integer);
  s:=jsonb_set(s,'{pending}',s->'pending'||jsonb_build_array(e));
 elsif effect_ in ('forced_miss','forced_letter') then
  a:=s->target_;
  if not(a->>'finished')::boolean and (effect_='forced_miss' or (a->>'index')::integer=(p_event->>'word_index')::integer) then
   word_:=versus_private.tower_duel_word(s,target_);alphabet_:=case when s->>'language'='es' then 'QWERTYUIOPASDFGHJKLÑZXCVBNM' else 'QWERTYUIOPASDFGHJKLZXCVBNM' end;
   select substr(alphabet_,i,1) into letter_ from generate_series(1,length(alphabet_)) i where position(substr(alphabet_,i,1) in word_)=0 and not(a->'letters' @> jsonb_build_array(substr(alphabet_,i,1))) order by random() limit 1;
   if letter_ is not null then s:=versus_private.tower_duel_letter(s,target_,letter_,p_now);end if;
  end if;
 else
  s:=jsonb_set(s,array[target_],s->target_||jsonb_build_object('effect',effect_,'effect_until',p_now+interval '5 seconds'));
 end if;
 s:=versus_private.tower_duel_event(s,jsonb_build_object('type','impact','actor',actor_,'target',target_,'effect',effect_,'hint',case when effect_='hint' and actor_='player' then p_event->>'hint' else null end));
 return versus_private.tower_duel_resolve(s,p_now);
end $$;
create function versus_private.tower_duel_input(p_state jsonb,p_action text,p_payload jsonb,p_now timestamptz)
returns jsonb language plpgsql security definer set search_path='' as $$
declare s jsonb:=p_state;a jsonb;effect_ text;
begin
 if p_action='start' then
  if (s->>'started')::boolean then return versus_private.tower_duel_advance(s,p_now);end if;
  s:=s||jsonb_build_object('started',true,'started_at',p_now,'next_tick',p_now+make_interval(secs=>(s->'config'->>'interval')::numeric/1000));
  return jsonb_set(jsonb_set(s,'{player,deadline}',to_jsonb(p_now+interval '240 seconds')),'{npc,deadline}',to_jsonb(p_now+interval '240 seconds'));
 end if;
 s:=versus_private.tower_duel_advance(s,p_now);
 if (s->>'finished')::boolean then return s;end if;
 if p_action='abandon' then return s||jsonb_build_object('finished',true,'winner','abandoned','done',false,'finished_at',p_now);end if;
 if not(s->>'started')::boolean then
  if p_action='resume' then return s;end if;
  raise exception 'Tower fight not started' using errcode='22023';
 end if;
 if p_action in ('tick','resume') then return s;end if;
 if p_action='ability' then return versus_private.tower_duel_ability(s,'player',p_now);end if;
 a:=s->'player';effect_:=case when (a->>'effect_until')::timestamptz>p_now then a->>'effect' else '' end;
 if (a->>'index')::integer<>(p_payload->>'word')::integer then return s||jsonb_build_object('feedback','stale_word');end if;
 if effect_ in ('roots','black_hole','key_bounce','ice_screen','key_theft','time_steal','forced_miss') then return s||jsonb_build_object('feedback','blocked');end if;
 return versus_private.tower_duel_letter(s,'player',p_payload->>'letter',p_now);
end $$;
create function versus_private.tower_duel_view(p_state jsonb,p_now timestamptz)
returns jsonb language plpgsql security definer set search_path='' as $$
declare s jsonb:=p_state;result jsonb;actor_ text;a jsonb;word_ text;display_ text;mask_ jsonb;until_ timestamptz;
begin
 result:=jsonb_build_object('started',s->'started','finished',s->'finished','winner',s->'winner','done',s->'done','character',s->'config'->>'rival','playerCharacter',s->'config'->>'player','event_seq',s->'event_seq','events',(select coalesce(jsonb_agg(case when value->>'actor'='npc' then value-array['letter','hint'] else value end),'[]') from jsonb_array_elements(s->'events')),'feedback',s->>'feedback');
 foreach actor_ in array array['player','npc'] loop
  a:=s->actor_;word_:=versus_private.tower_duel_word(s,actor_);
  select w.word into display_ from versus_private.tower_duel_bank(s->>'language',a->>'bankVersion') w where w.theme=a->>'theme' and w.word_id=(a->'words'->>((a->>'index')::integer))::integer;
  select coalesce(jsonb_agg(case when a->'letters' @> jsonb_build_array(substr(word_,i,1)) then to_jsonb(case when actor_='npc' then '?' else substr(display_,i,1) end) else 'null'::jsonb end order by i),'[]'::jsonb) into mask_ from generate_series(1,coalesce(length(word_),0)) i;
  until_:=case when (s->>'finished')::boolean then (s->>'finished_at')::timestamptz else p_now end;
  result:=jsonb_set(result,array[actor_],(a-array['words','bankVersion'])||jsonb_build_object('letters',case when actor_='npc' then '[]'::jsonb else a->'letters' end,'hint',case when actor_='npc' then '' else a->>'hint' end,'mask',mask_,'remaining',case when not(s->>'started')::boolean then 240 else greatest(0,ceil(extract(epoch from (a->>'deadline')::timestamptz-until_))::integer) end,'effectRemaining',greatest(0,ceil(extract(epoch from (a->>'effect_until')::timestamptz-p_now)*1000))::integer,'effect',case when (a->>'effect_until')::timestamptz>p_now then a->>'effect' else '' end));
 end loop;
 return result;
end $$;

create function versus_private.tower_character_allowed(p_user uuid,p_character text)
returns boolean language sql stable security definer set search_path='' as $$
 select case when p_character='explorador' then true
 when p_character in ('hombre_lobo','kairos','kalamo','guardian_alba','t_shadow') then exists(select 1 from versus_private.character_inventory where user_id=p_user and p_character=any(owned))
 else exists(select 1 from versus_private.verified_adventure_completions where user_id=p_user and mission=9 and world=case p_character when 'guardiana' then 0 when 'mago' then 1 when 'dragon' then 2 when 'dragon_hielo' then 3 when 'azrak' then 4 else -1 end) end
$$;
create function versus_private.tower_attempt_view(p_attempt versus_private.tower_attempts,p_now timestamptz)
returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('id',p_attempt.id,'character',d.character_key,'floor',d.floor,'rival',d.rival,'language',p_attempt.language,'status',p_attempt.status,'sequence',p_attempt.sequence,'completedFloors',coalesce((select completed from versus_private.tower_progress where user_id=p_attempt.user_id and character_key=d.character_key),0),'detail',versus_private.tower_duel_view(p_attempt.state,p_now)) from versus_private.tower_definitions d where d.key=p_attempt.definition
$$;
create function versus_private.tower_game(p_action text,p_attempt uuid,p_request uuid,p_sequence bigint,p_payload jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();now_ timestamptz:=versus_private.tower_server_now();c versus_private.tower_rollout;
 a versus_private.tower_attempts;d versus_private.tower_definitions;prior versus_private.tower_action_receipts;rec versus_private.tower_coin_receipts;
 response_ jsonb;state_ jsonb;allowed_ boolean;paid_ boolean:=false;definition_ text;theme_ text;bag_ text[];language_ text;reduced_ boolean;union_ boolean;
begin
 if u is null or not exists(select 1 from auth.users where id=u and not is_anonymous and (email_confirmed_at is not null or phone_confirmed_at is not null)) then raise exception 'Tower requires a verified permanent account' using errcode='42501';end if;
 if p_action is null or p_action not in ('status','begin','start','letter','ability','tick','resume','abandon','settle') or p_payload is null or jsonb_typeof(p_payload)<>'object' or octet_length(p_payload::text)>2048 then raise exception 'Invalid Tower action' using errcode='22023';end if;
 select * into strict c from versus_private.tower_rollout where singleton for share;
 allowed_:=c.enabled and (c.global_enabled or coalesce(u=any(c.pilot_users),false));
 if p_action='status' then
  if p_payload<>'{}'::jsonb or p_attempt is not null or p_request is not null or p_sequence is not null then raise exception 'Invalid Tower status parameters';end if;
  return jsonb_build_object('userId',u,'enabled',allowed_,'paymentsEnabled',allowed_ and c.payments_enabled,
   'progress',(select jsonb_agg(jsonb_build_object('character',ch.character_key,'completed',coalesce(p.completed,0),'eligible',versus_private.tower_character_allowed(u,ch.character_key)) order by ch.character_key) from (select distinct character_key from versus_private.tower_definitions) ch left join versus_private.tower_progress p on p.user_id=u and p.character_key=ch.character_key),
   'cleared',(select coalesce(jsonb_agg(jsonb_build_object('character',v.character_key,'floor',v.floor,'claimed',r.id is not null)),'[]') from versus_private.tower_verified_floors v left join versus_private.tower_coin_receipts r using(user_id,character_key,floor) where v.user_id=u),
   'pendingRewards',(select coalesce(jsonb_agg(id),'[]') from (select distinct on(t.definition) t.id from versus_private.tower_attempts t join versus_private.tower_definitions td on td.key=t.definition where t.user_id=u and t.status='won' and not exists(select 1 from versus_private.tower_coin_receipts r where r.user_id=u and r.character_key=td.character_key and r.floor=td.floor) order by t.definition,t.created_at desc limit 110) q),
   'activeAttempt',(select jsonb_build_object('id',t.id,'character',td.character_key,'floor',td.floor,'language',t.language) from versus_private.tower_attempts t join versus_private.tower_definitions td on td.key=t.definition where t.user_id=u and t.status in ('prepared','playing')));
 end if;
 if p_request is null then raise exception 'Tower request ID required' using errcode='22023';end if;
 -- The per-user lock serializes begin/recovery/settlement without involving other modes.
 perform pg_advisory_xact_lock(hashtextextended('tower:'||u::text,0));
 if p_action='begin' then
  if not allowed_ then raise exception 'Tower validation disabled' using errcode='42501';end if;
  if p_attempt is not null or p_sequence is not null or p_payload-array['character','floor','language','reducedMotion']<>'{}'::jsonb
    or jsonb_typeof(p_payload->'character') is distinct from 'string' or jsonb_typeof(p_payload->'floor') is distinct from 'number'
    or (p_payload->>'floor')!~ '^(10|[1-9])$' or coalesce(p_payload->>'language','') not in ('es','en','pt-BR')
    or (p_payload?'reducedMotion' and jsonb_typeof(p_payload->'reducedMotion')<>'boolean') then raise exception 'Invalid Tower start parameters' using errcode='22023';end if;
  definition_:=(p_payload->>'character')||':'||(p_payload->>'floor');language_:=p_payload->>'language';reduced_:=coalesce((p_payload->>'reducedMotion')::boolean,false);
  select * into a from versus_private.tower_attempts where user_id=u and request_id=p_request;
  if found then
   if a.definition<>definition_ or a.language<>language_ or (a.state->>'reduced')::boolean<>reduced_ then raise exception 'Tower request ID reused with different content';end if;
   return jsonb_build_object('userId',u,'attempt',versus_private.tower_attempt_view(a,now_));
  end if;
  select * into d from versus_private.tower_definitions where key=definition_;
  if not found or not versus_private.tower_character_allowed(u,d.character_key) then raise exception 'Tower character not owned or verified' using errcode='42501';end if;
  if d.floor>coalesce((select completed+1 from versus_private.tower_progress where user_id=u and character_key=d.character_key),1) then raise exception 'TOWER_FLOOR_LOCKED' using errcode='42501';end if;
  if exists(select 1 from versus_private.tower_attempts where user_id=u and status in ('prepared','playing')) then raise exception 'Recover the existing Tower attempt before starting another';end if;
  -- Browser history is not imported. Replays are allowed only within server-unlocked floors.
  select remaining into bag_ from versus_private.tower_category_rotation where user_id=u and character_key=d.character_key for update;
  if cardinality(bag_)=0 then select array_agg(theme order by random()) into bag_ from versus_private.tower_pools where definition=d.key and language=language_;end if;
  theme_:=bag_[1];update versus_private.tower_category_rotation set remaining=coalesce(bag_[2:cardinality(bag_)],'{}') where user_id=u and character_key=d.character_key;
  select exists(select 1 from versus_private.aren_access acc join versus_private.game_wallets w on w.user_id=acc.user_id where acc.user_id=u and acc.union_enabled and w.equipped->>'explorador'='aren-union') into union_;
  state_:=jsonb_build_object('config',d.config||jsonb_build_object('playerUnion',union_ and d.character_key='explorador'),'language',language_,'reduced',reduced_,'started',false,'finished',false,'winner','','done',false,'player',versus_private.tower_duel_actor(d.key,language_),'npc',versus_private.tower_duel_actor(d.key,language_,theme_),'pending','[]'::jsonb,'events','[]'::jsonb,'event_seq',0);
  return jsonb_build_object('userId',u,'attempt',versus_private.tower_attempt_view(a,now_));
 end if;
 if p_attempt is null or (p_action not in ('letter') and p_payload<>'{}'::jsonb) then raise exception 'Invalid Tower attempt parameters';end if;
 if p_action='letter' and (p_payload-array['letter','word']<>'{}'::jsonb or jsonb_typeof(p_payload->'letter') is distinct from 'string' or jsonb_typeof(p_payload->'word') is distinct from 'number' or coalesce(p_payload->>'word','')!~ '^[0-9]$' or length(p_payload->>'letter')<>1) then raise exception 'Invalid Tower letter payload';end if;
 select * into a from versus_private.tower_attempts where id=p_attempt and user_id=u;
 if not found then raise exception 'Tower attempt unavailable' using errcode='42501';end if;
 if p_action='settle' then
  if a.status<>'won' or a.state->>'winner'<>'player' or not(a.state->>'finished')::boolean then raise exception 'Tower victory not verified' using errcode='42501';end if;
  -- Match existing wallet lock order. No lock held by a normal action waits on a wallet.
  if allowed_ and c.payments_enabled then
   perform 1 from versus_private.game_wallets where user_id=u for update;
  end if;
  select * into a from versus_private.tower_attempts where id=p_attempt and user_id=u for update;
  select * into strict d from versus_private.tower_definitions where key=a.definition;
  if allowed_ and c.payments_enabled then
   if found then
    paid_:=true;update versus_private.game_wallets set coins=coins+rec.amount,revision=revision+1 where user_id=u;
   else select * into rec from versus_private.tower_coin_receipts where user_id=u and character_key=d.character_key and floor=d.floor;end if;
  end if;
  return jsonb_build_object('userId',u,'attempt',versus_private.tower_attempt_view(a,now_),'newlyCredited',paid_,'pending',rec.id is null,'receipt',case when rec.id is null then null else jsonb_build_object('id',rec.id,'userId',u,'attemptId',rec.attempt_id,'character',rec.character_key,'floor',rec.floor,'amount',rec.amount,'confirmed',true) end,'wallet',(select jsonb_build_object('coins',coins,'revision',revision) from versus_private.game_wallets where user_id=u));
 end if;
 if not allowed_ and p_action not in ('resume','abandon') then raise exception 'Tower validation disabled' using errcode='42501';end if;
 select * into a from versus_private.tower_attempts where id=p_attempt and user_id=u for update;
 select * into prior from versus_private.tower_action_receipts where attempt_id=a.id and request_id=p_request;
 if found then
  if prior.action<>p_action or prior.payload<>p_payload or prior.expected_sequence is distinct from p_sequence then raise exception 'Tower action ID reused with different content';end if;
  return prior.response;
 end if;
 if a.sequence>=4096 or (select count(*) from versus_private.tower_action_receipts where attempt_id=a.id)>=4096 then raise exception 'Tower action limit exceeded';end if;
 if p_action<>'resume' and (p_sequence is null or p_sequence<0 or p_sequence<>a.sequence) then return jsonb_build_object('userId',u,'stale',true,'attempt',versus_private.tower_attempt_view(a,now_));end if;
 now_:=greatest(now_,a.updated_at);
 if a.status in ('prepared','playing') then
  if a.status='prepared' and now_>a.created_at+interval '15 minutes' then state_:=a.state||jsonb_build_object('finished',true,'winner','expired','finished_at',now_);else state_:=versus_private.tower_duel_input(a.state,p_action,p_payload,now_);end if;
  update versus_private.tower_attempts set state=state_,sequence=sequence+1,updated_at=now_,status=case when (state_->>'finished')::boolean then case state_->>'winner' when 'player' then 'won' when 'npc' then 'lost' when 'abandoned' then 'abandoned' when 'expired' then 'expired' else 'draw' end when (state_->>'started')::boolean then 'playing' else 'prepared' end where id=a.id returning * into a;
  if a.status='won' then
   select * into strict d from versus_private.tower_definitions where key=a.definition;
    on conflict(user_id,character_key) do update set completed=greatest(tower_progress.completed,excluded.completed),updated_at=excluded.updated_at;
  end if;
 end if;
 response_:=jsonb_build_object('userId',u,'attempt',versus_private.tower_attempt_view(a,now_));
 return response_;
end $$;

do $acl$ declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='versus_private' and p.proname like 'tower\_%' escape '\' loop execute 'revoke all on function '||f.signature||' from public,anon,authenticated,service_role';end loop;end $acl$;
grant execute on function versus_private.tower_game(text,uuid,uuid,bigint,jsonb) to authenticated;
create function public.tower_game(p_action text default 'status',p_attempt uuid default null,p_request uuid default null,p_sequence bigint default null,p_payload jsonb default '{}') returns jsonb language sql security invoker set search_path='' as $$select versus_private.tower_game(p_action,p_attempt,p_request,p_sequence,p_payload)$$;
revoke all on function public.tower_game(text,uuid,uuid,bigint,jsonb) from public,anon,authenticated,service_role;
grant execute on function public.tower_game(text,uuid,uuid,bigint,jsonb) to authenticated;
notify pgrst,'reload schema';
